// hero.js wallet gains the chain (snapshot kept as alias for the active zone):
h.wallet = { current: {coins, energy, kills}, snapshots: {} };

// lifecycle.js:
export function recordZoneSnapshot(h) {
  const id = `${h.currentLevel}:${h.currentArea}`;
  h.wallet.snapshots[id] = { coins: h.wallet.current.coins, score: /* current computed score */ };
}
export function restoreZoneState(h, zoneId) {
  const s = h.wallet.snapshots[zoneId];
  if (!s) return;
  h.wallet.current.coins = s.coins; // score derives from trace — see doc §1
}

// death restart (startLife):
restoreZoneState(h, currentZoneId(h)); // was restoreAreaEntryStats
resetHeroInventory(h);                 // energy full + weapon gone (existing)

// manual retry (pause menu) — same price as dying:
export function manualRetry(h) {
  if (!canSpend(livesPool(h))) return false;
  spend one life;
  // identical reset sequence to a death restart
}

// continueRun:
spend(h.continues);
h.lives = GAME_RULES.startingLives;
h.currentArea = ENTRY_AREA;
restoreZoneState(h, `${h.currentLevel}:1`); // replaces resetLevelCoinTally
resetHeroInventory(h);                        // same as die
beginContinue(h); h._lifeBucketArmed = true;

// on level advance (reward confirmed):
h.energy = h.maxEnergy; // ONLY energy changes
// lives, continues, wallet, weapon, specials: untouched

// saveCurrentRun meta gains:
state: { coins, score, energy, weapon, specialSlots, lives, continues },
snapshots: h.wallet.snapshots, // the whole zone chain

// update.js MENU->AREA_ENTRY hook (after seed rebuild):
if (sm.state) applySavedState(hero, sm); // wallet, inventory, lives, continues, snapshots
isValidSaveMeta tolerates legacy saves without state (fallback = today's behavior)

// helper: script a run to zone 1-3 with known coin/score deltas, then:
// die()        -> expect 1-3 snapshot coins, full energy, default weapon, lives-1
// manualRetry()-> same as die, lives-1
// continue()   -> expect 1-1 snapshot coins, full energy, default weapon, lives refilled, continues-1
// advanceZone()-> everything kept
// clearLevel() -> energy full, lives kept
// save/reload  -> full state round-trip
